#!/usr/bin/env bun
/**
 * LearnGate.hook.ts — Enforce LEARN phase persistence (PreToolUse)
 *
 * PURPOSE:
 * Blocks PRD.md from being set to `phase: complete` unless a LEARN.md file
 * exists in the same PRD directory. This guarantees that Algorithm LEARN phase
 * reflections are persisted to disk before the session is marked complete.
 *
 * TRIGGER: PreToolUse (matcher: Edit, Write)
 *
 * INPUT:
 * - tool_name: "Edit" | "Write"
 * - tool_input: { file_path, old_string?, new_string?, content? }
 *
 * OUTPUT:
 * - {"continue": true} → Allow operation (not a PRD.md or not phase: complete)
 * - {"decision": "block", "reason": "..."} → Block until LEARN.md exists
 *
 * PERFORMANCE: <5ms. Pure filesystem check, no AI inference.
 */

import { existsSync } from 'fs';
import { dirname, join } from 'path';

let input: any;
try {
  input = JSON.parse(require('fs').readFileSync(0, 'utf-8'));
} catch {
  console.log(JSON.stringify({ continue: true }));
  process.exit(0);
}

const toolInput = input.tool_input || {};
const filePath: string = toolInput.file_path || '';

// Only check PRD.md files in MEMORY/WORK/
if (!filePath.includes('MEMORY/WORK/') || !filePath.endsWith('PRD.md')) {
  console.log(JSON.stringify({ continue: true }));
  process.exit(0);
}

// Detect if this edit/write sets phase to "complete"
let setsPhaseComplete = false;

if (input.tool_name === 'Edit') {
  const newString: string = toolInput.new_string || '';
  // Match "phase: complete" in the new_string (frontmatter edit)
  setsPhaseComplete = /phase:\s*complete/i.test(newString);
} else if (input.tool_name === 'Write') {
  const content: string = toolInput.content || '';
  // For full writes, check if the frontmatter section contains phase: complete
  const frontmatterMatch = content.match(/^---\n([\s\S]*?)\n---/);
  if (frontmatterMatch) {
    setsPhaseComplete = /phase:\s*complete/i.test(frontmatterMatch[1]);
  }
}

if (!setsPhaseComplete) {
  console.log(JSON.stringify({ continue: true }));
  process.exit(0);
}

// Check if LEARN.md exists in the PRD directory
const prdDir = dirname(filePath);
const learnPath = join(prdDir, 'LEARN.md');

if (existsSync(learnPath)) {
  // LEARN.md exists — allow phase: complete
  console.log(JSON.stringify({ continue: true }));
} else {
  // LEARN.md missing — block the transition
  console.log(JSON.stringify({
    decision: 'block',
    reason: `LEARN phase requires persistence: write LEARN.md to ${prdDir}/ before setting phase: complete. Template: ## Reflections (what to do differently), ## Patterns (reusable insights), ## Actions (MEMORY/WISDOM files to create).`
  }));
}

